<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('PUT','POST');apiCsrf();$uid=apiAuth();$in=apiInput();$item=apiId($in['item_id']??0);$qty=(int)($in['quantity']??0);if($qty<1)apiError('Invalid quantity',422);$s=apiDb()->prepare('UPDATE cart_items ci JOIN carts c ON c.id=ci.cart_id SET ci.quantity=? WHERE ci.id=? AND c.user_id=?');$s->execute([$qty,$item,$uid]);if(!$s->rowCount())apiError('Item not found',404);apiResponse(['id'=>$item,'quantity'=>$qty]);